def seed_resources(apps, schema_editor):
    AdditionalResource = apps.get_model("app", "AdditionalResource")
    for row in RESOURCES:
        resource, created = AdditionalResource.objects.get_or_create(
            category=row["category"],
            title=row["title"],
            defaults={
                "author": row["author"],
                "url": row["url"],
                "display_order": row["display_order"],
            },
        )
        if not resource.cover_image:
            cover_path = COVERS_DIR / row["cover"]
            if cover_path.exists():
                with cover_path.open("rb") as fh:
                    resource.cover_image.save(cover_path.name, File(fh), save=True)


def unseed_resources(apps, schema_editor):
    AdditionalResource = apps.get_model("app", "AdditionalResource")
    for row in RESOURCES:
        AdditionalResource.objects.filter(category=row["category"], title=row["title"]).delete()


